node -e "
import('node:fs').then(fs => {
  const pkg = './node_modules/@re-cinq/eslint-plugin-re-lint';
  const list = (d) => fs.readdirSync(d, {withFileTypes:true}).flatMap(e => e.isDirectory() ? list(d+'/'+e.name) : [d+'/'+e.name]);
  const files = list(pkg).filter(f => /colocated|subject|max-expects|vague|duplicate/.test(f));
  for (const f of files) { console.log('=== ' + f + ' ==='); console.log(fs.readFileSync(f, 'utf8')); }
});
"

