node -e "
Promise.all([import('prettier'), import('node:fs')]).then(async ([prettier, fs]) => {
  const file = 'src/orchestration/chatOrchestrator.acceptance.test.ts';
  const src = fs.readFileSync(file, 'utf8');
  const cfg = JSON.parse(fs.readFileSync('.prettierrc', 'utf8'));
  const formatted = await prettier.default.format(src, {...cfg, filepath: file});
  console.log('matches prettier:', src === formatted);
  if (src !== formatted) console.log(formatted);
});
"
